verifyScriptWindows:
if (-not (Test-Path 'summary.txt')) { exit 1 }
$content = Get-Content 'summary.txt' -Raw
if ($content -match 'alpha=red' -and $content -match 'beta=green' -and $content -match 'total=2') { exit 0 }
Write-Host $content
exit 1

if (-not (Test-Path 'command-guard-ok.txt')) { exit 1 }
$content = Get-Content 'command-guard-ok.txt' -Raw
$audit = Get-ChildItem 'audit' -Filter 'audit-*.jsonl' -ErrorAction SilentlyContinue | ForEach-Object { Get-Content $_.FullName -Raw }
if ($content -match 'command guard refused unsafe command' -and $audit -match '"tool":"execute_command"' -and $audit -match '"outcome":"deny"' -and $audit -match '"approver":"policy"') { exit 0 }
Write-Host $content
Write-Host $audit
exit 1

if (-not (Test-Path 'plan-output.txt')) { exit 1 }
$content = Get-Content 'plan-output.txt' -Raw
if ($content -match 'copied=plan seed=42' -and $content -match 'status=planned') { exit 0 }
Write-Host $content
exit 1

if (Test-Path 'blocked-by-hook.txt') { exit 1 }
if (-not (Test-Path 'hook-allowed.txt')) { exit 1 }
$allowed = Get-Content 'hook-allowed.txt' -Raw
$log = Get-Content 'hook-log.jsonl' -Raw -ErrorAction SilentlyContinue
if ($allowed -match 'hook allowed after denial' -and $log -match 'blocked-by-hook.txt') { exit 0 }
Write-Host $allowed
Write-Host $log
exit 1
